<script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js"></script>
<script>
const $=id=>document.getElementById(id);let files=[],sources=[],reportHtml='';
$('year').textContent=new Date().getFullYear();if(window.pdfjsLib)pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
function showStep(n){[1,2,3,4].forEach(i=>{$('step'+i).classList.toggle('hidden',i!==n);let el=document.querySelector('[data-step-label="'+i+'"]');el.classList.toggle('active',i===n);el.classList.toggle('done',i<n);});window.scrollTo({top:0,behavior:'smooth'});}
function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function addFiles(list){for(const f of list){if(files.some(x=>x.name===f.name&&x.size===f.size))continue;files.push(f);}renderFiles();}
function renderFiles(){$('fileList').innerHTML=files.map((f,i)=>'<div class="file-row"><i class="bi '+(f.type==='application/pdf'?'bi-file-pdf':f.type.startsWith('image/')?'bi-image':'bi-file-earmark-word')+'"></i><span class="text-truncate">'+escapeHtml(f.name)+'</span><small class="text-secondary">'+(f.size/1024).toFixed(0)+' KB</small><button class="btn btn-sm btn-link text-danger" onclick="removeFile('+i+')" aria-label="Remove file"><i class="bi bi-x-lg"></i></button></div>').join('');}
function removeFile(i){files.splice(i,1);renderFiles();}
$('files').addEventListener('change',e=>addFiles([...e.target.files]));const dz=$('dropzone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('drag')});dz.addEventListener('dragleave',()=>dz.classList.remove('drag'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('drag');addFiles([...e.dataTransfer.files]);});
async function extractFile(f){let ext=f.name.split('.').pop().toLowerCase();if(ext==='txt')return await f.text();if(ext==='docx'){if(!window.mammoth)throw Error('DOCX reader did not load');let r=await mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()});return r.value;}if(ext==='pdf'){if(!window.pdfjsLib)throw Error('PDF reader did not load');let pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,all=[];for(let p=1;p<=pdf.numPages;p++){let page=await pdf.getPage(p),c=await page.getTextContent();all.push(c.items.map(x=>x.str).join(' '));}return all.join('\n\n');}if(f.type.startsWith('image/'))return '[Image attachment: '+f.name+'. Image is included as supporting evidence but text inside the image has not been extracted.]';throw Error('Unsupported file type: '+f.name);}
$('to2').onclick=()=>{if(!files.length&&!$('title').value.trim()){alert('Upload at least one source document.');return;}showStep(2)};$('back1').onclick=()=>showStep(1);
$('to3').onclick=async()=>{if(!files.length){alert('Please upload at least one source document.');showStep(1);return;}let btn=$('to3');btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Reading documents...';sources=[];try{for(const f of files){let text=await extractFile(f);sources.push({name:f.name,text});}}catch(e){alert('Could not read a file: '+e.message);btn.disabled=false;btn.textContent='Review report →';return;}btn.disabled=false;btn.innerHTML='Review report <i class="bi bi-arrow-right ms-1"></i>';let all=sources.map(s=>s.text).join('\n\n');$('sourceCount').textContent=files.length+' source files';$('wordCount').textContent=all.trim()?all.trim().split(/\s+/).length+' extracted words':'0 extracted words';$('reviewSummary').innerHTML='<b>Report type:</b> '+escapeHtml($('type').value)+'<br><b>Subject:</b> '+escapeHtml($('title').value||deriveTitle(all)||'Needs confirmation from the source documents')+'<br><b>Language:</b> '+escapeHtml($('language').value);$('sourcePreview').innerHTML=sources.map(s=>'<h6 class="fw-bold">'+escapeHtml(s.name)+'</h6><p>'+escapeHtml(s.text.slice(0,2600)||'No readable text found in this file.')+(s.text.length>2600?'…':'')+'</p><hr>').join('');showStep(3);};$('back2').onclick=()=>showStep(2);
function deriveTitle(text){let lines=text.split(/[\n.!?]+/).map(x=>x.trim()).filter(x=>x.length>12&&x.length<115);let avoid=/^(chapter|table of contents|university|declaration|acknowledgement|abstract|introduction|references)/i;return lines.find(x=>!avoid.test(x))||'';}
function getSections(type){let common=['Introduction and Background','Objectives and Scope','Methodology / Approach','Main Activities, Analysis or Implementation','Results and Discussion','Challenges and Limitations','Conclusion','Recommendations','References'];if(type.includes('Training'))return ['Introduction','Profile of the Host Organisation','Objectives of Industrial Training','Departmental Structure and Work Environment','Activities and Tasks Performed','Skills and Knowledge Acquired','Challenges Encountered and Solutions','Relationship Between Theory and Practice','Conclusion','Recommendations','References','Appendices'];if(type.includes('Internship'))return ['Introduction','Host Organisation Profile','Internship Objectives and Expectations','Roles and Responsibilities','Work Undertaken','Skills and Professional Development','Challenges and Lessons Learned','Conclusion','Recommendations','References','Appendices'];if(type.includes('Research'))return ['Introduction','Background to the Study','Statement of the Problem','Objectives and Research Questions','Literature Review','Research Methodology','Presentation and Analysis of Findings','Discussion','Conclusion','Recommendations','References','Appendices'];if(type.includes('Project'))return ['Introduction and Project Background','Problem Statement','Objectives and Scope','Requirements Analysis','Design and Methodology','Implementation / Development','Testing and Results','Discussion','Conclusion','Recommendations','References','Appendices'];if(type.includes('Business'))return ['Executive Summary','Business Background and Context','Objectives and Scope','Market / Operational Analysis','Methodology and Evidence','Findings and Performance Analysis','Risks and Challenges','Conclusion','Recommendations and Action Plan','References','Appendices'];return common.concat(['References','Appendices']);}
function relevantText(text,max=4500){let clean=text.replace(/\s+/g,' ').trim();return clean.length>max?clean.slice(0,max)+'…':clean;}
function buildReport(){let type=$('type').value,subject=$('title').value.trim()||deriveTitle(sources.map(s=>s.text).join(' '))||'[Confirm report subject from source documents]';let author=$('author').value||'[Author name required]',inst=$('institution').value||'[Institution / organisation required]',dept=$('department').value||'[Department / programme]',sup=$('supervisor').value||'[Supervisor, if applicable]',loc=$('location').value||'[Location, if applicable]',period=$('period').value||'[Reporting period]';let req=$('requirements').value,notes=$('notes').value,all=sources.map(s=>s.text).filter(t=>!t.startsWith('[Image attachment')).join('\n\n');let lang=$('language').value;let sections=getSections(type);let paragraphs=all?'<p>'+escapeHtml(relevantText(all,7000))+'</p>':'<p>[No machine-readable text was extracted. Add verified source content before submission.]</p>';let out='<div style="text-align:center;min-height:650px;display:flex;flex-direction:column;justify-content:center"><div style="font-size:13px;letter-spacing:3px;color:#2457d6;font-weight:bold">RAYMOND REPORT GENERATOR</div><h1 style="font-size:30px;margin:45px 0 18px">'+escapeHtml(subject)+'</h1><h3>'+escapeHtml(type)+'</h3><p style="margin-top:55px"><b>Prepared by</b><br>'+escapeHtml(author)+'</p><p><b>'+escapeHtml(inst)+'</b><br>'+escapeHtml(dept)+'</p><p><b>Supervisor:</b> '+escapeHtml(sup)+'</p><p><b>Location:</b> '+escapeHtml(loc)+'</p><p><b>Period:</b> '+escapeHtml(period)+'</p><p style="margin-top:80px"> '+new Date().getFullYear()+'</p></div><div style="page-break-before:always"></div><h2>DECLARATION</h2><p>I declare that this report, titled “'+escapeHtml(subject)+'”, is prepared using the source materials and information identified by the author. All statements, data and references must be checked for accuracy and acknowledged according to the institution’s requirements.</p><p>Signature: ____________________ &nbsp;&nbsp; Date: ____________________</p><h2>ACKNOWLEDGEMENTS</h2><p>[Add acknowledgements to the individuals and organisations who provided genuine support. This section is intentionally left for the author to complete.]</p><h2>ABSTRACT / EXECUTIVE SUMMARY</h2><p>This report addresses '+escapeHtml(subject)+'. It is based on the documents supplied by the author and the requirements selected during report preparation. A final summary of the purpose, approach, key evidence, findings and recommendations should be completed after verifying the full report.</p><h2>TABLE OF CONTENTS</h2><ol>'+sections.map(s=>'<li>'+escapeHtml(s)+'</li>').join('')+'</ol>';sections.forEach((s,i)=>{out+='<h2>CHAPTER '+(i+1)+': '+escapeHtml(s.toUpperCase())+'</h2>';if(i===0)out+='<p>This report is titled “'+escapeHtml(subject)+'”. It is prepared as a '+escapeHtml(type.toLowerCase())+' using the supplied source documents and the author’s selected requirements. The subject, scope and context must be confirmed against the original materials.</p>';if(i===1)out+='<p>'+escapeHtml(relevantText(all,2500)||'[Insert verified background information from the source documents.]')+'</p>';if(i===2)out+='<p><b>Author-provided instructions:</b></p><p>'+escapeHtml(req||'[Add the required objectives, questions, scope or institutional instructions.]')+'</p>';if(i===3||i===4)out+='<p><b>Source material reviewed:</b></p>'+paragraphs;if(i===sections.length-3)out+='<p><b>Additional information supplied by the author:</b></p><p>'+escapeHtml(notes||'[Insert verified findings, activities, analysis or supporting details. Do not include unverified claims.]')+'</p>';if(i===sections.length-2)out+='<p>Based on the evidence presented in the preceding sections, the report should state conclusions that directly answer its objectives and are supported by the source material. Complete this section after checking all facts and analysis.</p>';if(i===sections.length-1)out+='<p>[Add only sources actually consulted. Format citations and references using the required institutional style. Do not list sources that were not used.]</p>';if(i!==0&&i!==1&&i!==2&&i!==3&&i!==4&&i!==sections.length-3&&i!==sections.length-2&&i!==sections.length-1)out+='<p>[Develop this section using relevant evidence from the uploaded documents and additional verified information supplied by the author. Where information is missing, identify the gap rather than inventing details.]</p>';});out+='<h2>APPENDICES</h2><p>Attach supporting documents, approved forms, tables, photographs and other evidence here. Actual workplace photographs should be supplied by the author and labelled accurately.</p><hr><p><b>Source documents processed:</b> '+sources.map(s=>escapeHtml(s.name)).join('; ')+'</p><p><i>Preparation note: This draft was structured locally from uploaded files and user-entered requirements. It was not generated by an AI research service. Verify, expand and cite all content before academic or professional submission.</i></p>';return out;}
$('generate').onclick=()=>{if(!sources.length){alert('No readable source documents found.');return;}$('report').innerHTML=buildReport();showStep(4);};$('back3').onclick=()=>showStep(3);$('regenerate').onclick=()=>$('report').innerHTML=buildReport();
function getDoc(){let css='body{font-family:Arial,sans-serif;color:#202b3b;line-height:1.6}h1,h2,h3{color:#183c75}h2{border-bottom:1px solid #dce5f1;padding-bottom:7px;margin-top:28px}';return '<!doctype html><html><head><meta charset="utf-8"><title>Raymond Report</title><style>'+css+'@page{size:A4;margin:22mm}</style></head><body>'+ $('report').innerHTML+'</body></html>';}
$('download').onclick=()=>{let blob=new Blob(['\ufeff'+getDoc()],{type:'application/msword'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(($('title').value||'Raymond-Report').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,''))+'.doc';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);};
$('print').onclick=()=>{let w=window.open('','_blank');if(!w){alert('Please allow pop-ups to print the report.');return;}w.document.open();w.document.write(getDoc()+'<script>window.onload=function(){setTimeout(function(){window.print()},400)};<\/script>');w.document.close();};
$('newReport').onclick=()=>{if(confirm('Start a new report? Current unsaved edits will be cleared.')){files=[];sources=[];renderFiles();['title','author','institution','department','supervisor','location','period','requirements','notes'].forEach(id=>$(id).value='');$('report').innerHTML='';$('files').value='';showStep(1);}};
</script></body></html>